const { text, domainName, context, sessionId, userName, isStack } = $.input;
if (!text || !domainName) throw new Error('text and domainName are required');

const body = { Text: text, DomainName: domainName };
if (context) body.Context = context;
if (sessionId) body.SessionId = sessionId;
if (userName) body.UserName = userName;
if (isStack) body.is_stack = true;

return { body };

const resp = $.steps.sendMessage.response || {};
return {
  aiMessage: resp.ai_message || '',
  aiScore: resp.ai_score || 0,
  aiName: resp.ai_name || '',
  sessionId: resp.SessionId || '',
  summary: resp.ai_message ? `${resp.ai_name || 'AI'} responded (score: ${(resp.ai_score || 0).toFixed(1)})` : 'No response received'
};
